{
  "name": "opencode-session-identity",
  "version": "1.0.2",
  "description": "opencode plugin that exposes the current session id to the agent via shell env and system prompt",
  "type": "module",
  "main": "./session-identity.js",
  "exports": {
    ".": "./session-identity.js"
  },
  "files": [
    "session-identity.js",
    "README.md",
    "LICENSE"
  ],
  "keywords": [
    "opencode",
    "opencode-plugin",
    "plugin",
    "session",
    "audit",
    "observability"
  ],
  "author": "Henrique Van Klaveren",
  "license": "MIT",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/klaveren/opencode-session-identity.git"
  },
  "bugs": {
    "url": "https://github.com/klaveren/opencode-session-identity/issues"
  },
  "homepage": "https://github.com/klaveren/opencode-session-identity#readme",
  "scripts": {
    "test": "node --test",
    "release": "npm version patch && git push --follow-tags"
  },
  "engines": {
    "node": ">=18"
  },
  "publishConfig": {
    "access": "public",
    "registry": "https://registry.npmjs.org/"
  }
}
